def analyze_feature(data, energy_axis):
    import numpy as np
    arr = np.asarray(data)
    return {
        "maps": {
            "edge_jump": arr[:, :, -1] - arr[:, :, 0],
            "mean_map": arr.mean(axis=2),
        },
        "units": {"edge_jump": "a.u.", "mean_map": "a.u."},
        "description": "edge jump and mean intensity",
    }
